const fileNames={"1 Samuel":"1Samuel","2 Samuel":"2Samuel","1 Kings":"1Kings","2 Kings":"2Kings","1 Chronicles":"1Chronicles","2 Chronicles":"2Chronicles","Song of Solomon":"SongofSolomon","1 Corinthians":"1Corinthians","2 Corinthians":"2Corinthians","1 Thessalonians":"1Thessalonians","2 Thessalonians":"2Thessalonians","1 Timothy":"1Timothy","2 Timothy":"2Timothy","1 Peter":"1Peter","2 Peter":"2Peter","1 John":"1John","2 John":"2John","3 John":"3John"};
