const loadedBooks={};let currentBook="Genesis",currentChapter=1,currentDailyVerse;
const encouragements={peace:{title:"God Is Your Peace",verse:"Be still, and know that I am God.",reference:"Psalm 46:10",message:"Xyhime, you do not have to solve everything at once. Rest your heart in God's presence."},strength:{title:"God Will Strengthen You",verse:"Fear thou not; for I am with thee: be not dismayed; for I am thy God.",reference:"Isaiah 41:10",message:"You are not carrying today's weight alone."},anxiety:{title:"Give God Your Worries",verse:"Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God.",reference:"Philippians 4:6",message:"Place each worry before God one at a time."},faith:{title:"Keep Trusting",verse:"Trust in the LORD with all thine heart; and lean not unto thine own understanding.",reference:"Proverbs 3:5",message:"You do not need to see the entire road to trust the One leading you."},love:{title:"You Are Loved",verse:"We love him, because he first loved us.",reference:"1 John 4:19",message:"Before achievements or expectations, remember that you are deeply loved."},gratitude:{title:"Give Thanks",verse:"O give thanks unto the LORD; for he is good: for his mercy endureth for ever.",reference:"Psalm 136:1",message:"Notice the quiet blessings God has placed around you today."}};
